use serde_json::{Value,json};

pub async fn client<T:DeserializeOwned>(method:&str,path:&str,body:Value)->Result<T,String> {
    #[cfg(feature="hydrate")]{
        let request=gloo_net::http::RequestBuilder::new(path).method(method.parse().unwrap());
        let response=if method=="GET"{request.send().await}else{request.json(&body).map_err(|_|"Could not prepare your request.")?.send().await}.map_err(|_|"Could not reach the server. Your form is still here; please try again.")?;
        if !response.ok(){return Err(response.json::<Value>().await.ok().and_then(|v|v["error"].as_str().map(str::to_owned)).unwrap_or("Your request was not saved. Please try again.".into()));}
        response.json().await.map_err(|_|"Could not read the confirmation. Please retry this form.".into())
    }
    #[cfg(not(feature="hydrate"))]{let _=(method,path,body);Err("Opening your form…".into())}
}
fn heading(kind:&str)->&'static str {match kind{"giving"=>"A gift begins with a connection.","membership"=>"Find your place in the Alliance.","volunteer"=>"Bring your time. Share your skills.",_=>"Keep the trail in your life."}}
fn introduction(kind:&str)->&'static str {match kind{
    "giving"=>"Ask about supporting trail care, preserving history, or helping the next generation discover the trail.",
    "membership"=>"Ask about joining or renewing. Alliance memberships follow the calendar year, January through December.",
    "volunteer"=>"Tell the site team what you can offer and when you might be available. Opportunities depend on local needs, partners, and the season.",
    _=>"The Tripod is the Alliance’s member newsletter. Browse past issues, or register your interest in future updates."}}
fn action(kind:&str)->&'static str {match kind{"giving"=>"Save giving enquiry","membership"=>"Save membership enquiry","volunteer"=>"Save volunteer offer",_=>"Register newsletter interest"}}

#[component]
