    let all=cms::items("campaign");let projects:Vec<_>=all.iter().filter(|p|!p.field("project_status").is_empty()).cloned().collect();let other:Vec<_>=all.into_iter().filter(|p|p.field("project_status").is_empty()).collect();
    let events=cms::items("event");
    view!{<cms::ManagedIntro slug="get-involved" show_photo=false/>
        <section class="support-landscape support-project-hero"><img src=image.image() srcset=photography::srcset(&image) sizes="100vw" style=image.image_position() alt=image.field("image_alt") fetchpriority="high"/><div class="support-landscape-shade"/><div class="container"><span class="eyebrow">"PUT YOUR CARE INTO ACTION"</span><h2>"A clear trail."<br/>"A preserved story."<br/><em>"A part for you."</em></h2></div></section><div class="container support-photo-caption"><photography::PhotoAttribution item=image/></div>
        <nav class="interior-section-nav" aria-label="Support sections"><div class="container"><a href="#work-supported">"Work supported"</a><a href="#ways-to-help">"Ways to help"</a><a href="#volunteer">"Offer your skills"</a><a href=url("/support/newsletter")>"Stay connected"</a></div></nav>
        <section class="container support-purpose"><span class="eyebrow">"WHAT SUPPORT MAKES POSSIBLE"</span><h2>"Useful work."<br/><em>"Lasting connections."</em></h2><div><p>"Support helps the Alliance work with partners on trail maintenance, preserve first-person history, and connect people with Alaska’s natural and cultural heritage."</p><p>"The projects below show where that support has gone. An area of interest starts a conversation about future help; it does not earmark a gift to a completed project."</p><a class="text-link" href="https://www.iditarod100.org/annual-reports.html" target="_blank" rel="noopener noreferrer">"Read the Alliance’s reports"<Icon name="external"/></a></div></section>
        <section class="support-work" id="work-supported"><div class="container"><div class="section-heading"><div><span class="section-marker"><span>"01"</span>"DOCUMENTED WORK"</span><h2>"Here is what care looks like."</h2></div><p>"Real projects. Named partners. A record you can follow."</p></div><div class="support-project-grid">{projects.into_iter().enumerate().map(|(i,p)|view!{<ProjectCard item=p number=i+1/>}).collect_view()}</div></div></section>
        <section class="container support-choices" id="ways-to-help"><div class="section-heading"><div><span class="section-marker"><span>"02"</span>"CHOOSE YOUR NEXT STEP"</span><h2>"There is more than one way to help."</h2></div><p>"Bring a question, an idea, or an offer. The next step is clear."</p></div><div class="support-choice-grid">{[("giving","01 / GIVE","Help fund practical work.","Discuss a gift for the Alliance’s work: trail partnerships, history, and education."),("membership","02 / BELONG","Become part of the story.","Ask about joining or renewing a calendar-year membership."),("volunteer","03 / TAKE PART","Offer something only you can.","Share your skills, local knowledge, equipment, or available time."),("newsletter","04 / KEEP IN TOUCH","Follow the work forward.","Browse The Tripod and register interest in future updates.")].into_iter().map(|(kind,n,t,d)|view!{<article><span class="eyebrow">{n}</span><h3>{t}</h3><p>{d}</p><a class="text-link" href=url(&format!("/support/{kind}"))>{match kind{"giving"=>"Explore giving","membership"=>"Explore membership","volunteer"=>"Offer your help",_=>"Stay connected"}}<Icon/></a></article>}).collect_view()}</div></section>
        <section class="support-skills" id="volunteer"><div class="container"><div><span class="eyebrow">"TIME, SKILLS & LOCAL KNOWLEDGE"</span><h2>"Tell us what you can bring."</h2><p>"These are ways to express interest. A project, role, or work date is arranged separately with the people responsible for it."</p><a class="button button-green" href=url("/support/volunteer")>"Make a volunteer offer"<Icon/></a></div><div class="support-skill-list">{[("Trail care","Practical work, transport, equipment, and knowledge of local routes."),("History & stories","Research, archives, oral accounts, writing, and photography."),("Education & outreach","Place-based learning, community connections, and sharing resources.")].into_iter().map(|(t,d)|view!{<article><h3>{t}</h3><p>{d}</p></article>}).collect_view()}<a class="text-link" href="https://www.iditarod100.org/volunteer.html" target="_blank" rel="noopener noreferrer">"Explore the Alliance’s partner directory"<Icon name="external"/></a></div></div></section>
        {(!other.is_empty()).then(||view!{<section class="container participation-list"><h2>"More ways to contribute."</h2><div class="three-grid">{other.into_iter().map(|item|view!{<ContentCard item/>}).collect_view()}</div></section>})}
        {(!events.is_empty()).then(||view!{<section class="container participation-list"><h2>"Come together."</h2><div class="three-grid">{events.into_iter().map(|item|view!{<ContentCard item/>}).collect_view()}</div></section>})}}
