#[component]
pub fn Journey()->impl IntoView {
    let params=use_params_map();
    view!{{move||{let kind=params.get().get("kind").unwrap_or_default();if KINDS.iter().any(|(k,_,_)|*k==kind){view!{<JourneyForm kind/>}.into_any()}else{view!{<crate::pages::NotFound/>}.into_any()}}}}
}
#[component]
fn FormField(id:&'static str,label:&'static str,value:RwSignal<String>,#[prop(default="text")] input_type:&'static str,#[prop(default=false)] required:bool,#[prop(default=false)] multiline:bool,#[prop(default=2000)] max:usize)->impl IntoView {
    view!{<div class="support-field"><label for=id>{label}</label>{if multiline{view!{<textarea id=id rows="5" maxlength=max required=required prop:value=move||value.get() on:input=move|e|value.set(event_target_value(&e))/>}.into_any()}else{view!{<input id=id type=input_type required=required maxlength=max min="1" max="1000000" step="1" autocomplete=match id{"support-email"=>"email","support-name"=>"name",_=>"off"} prop:value=move||value.get() on:input=move|e|value.set(event_target_value(&e))/>}.into_any()}}</div>}
}
#[component]
fn JourneyForm(kind:String)->impl IntoView {
    let kind=StoredValue::new(kind);let kind_value=kind.get_value();let newsletter=kind_value=="newsletter";let query=use_query_map();let selected=query.get_untracked().get("interest").filter(|v|AREAS.iter().any(|(k,_)|*k==v)).unwrap_or("where-needed".into());
    let area=RwSignal::new(selected);let name=RwSignal::new(String::new());let email=RwSignal::new(String::new());let amount=RwSignal::new(String::new());let availability=RwSignal::new(String::new());let message=RwSignal::new(String::new());let website=RwSignal::new(String::new());let consent=RwSignal::new(false);let busy=RwSignal::new(false);let error=RwSignal::new(String::new());let key=RwSignal::new(String::new());
    let destination=cms::public_link(KINDS.iter().find(|(k,_,_)|*k==kind_value).unwrap().2);let external=destination.is_some();let nav=use_navigate();
    let load=move||spawn_local(async move{match client::<Value>("GET","/api/support/start",Value::Null).await{Ok(v)=>{key.set(v["key"].as_str().unwrap_or("").into());error.set(String::new());},Err(e)=>error.set(e)}});
    Effect::new(move |_|{if !external{load();}});
    view!{<Title text=format!("{} | The Living Trail",label(&kind_value))/><div class="container breadcrumb"><a href=url("/get-involved")>"Support the Alliance"</a><span>"/"</span><span>{label(&kind_value)}</span></div><section class="container support-journey"><header><span class="eyebrow">"A SMALL BEGINNING"</span><h1>{heading(&kind_value)}</h1><p>{introduction(&kind_value)}</p><div class="journey-steps"><span>"01 / Share your interest"</span><span>"02 / Receive a confirmation"</span><span>"03 / Plan the next step"</span></div><div class="journey-context"><h2>"A clear next step."</h2><p>{if external{"Continue to the Alliance’s selected service. Its checkout or signup page will confirm completion."}else if newsletter{"Your interest is saved for the site team. It does not start a mailing-list subscription. Keep your confirmation link to withdraw your request."}else{"Your enquiry is saved for the site team to review. Gifts, membership registration, and volunteer arrangements are completed separately."}}</p>{newsletter.then(||view!{<a class="text-link" href="https://www.iditarod100.org/newsletters.html" target="_blank" rel="noopener noreferrer">"Read The Tripod archive"<Icon name="external"/></a>})}<a class="text-link" href=url("/support/privacy")>"How your details are used"<Icon/></a></div></header>
        {if let Some(href)=destination{view!{<div class="support-form service-handoff"><span class="eyebrow">"CONTINUE WITH THE ALLIANCE’S SERVICE"</span><h2>"Ready for the next step."</h2><p>"You’ll choose your details and receive the final confirmation there."</p><a class="button button-green" href=href target="_blank" rel="noopener noreferrer">{match kind_value.as_str(){"giving"=>"Continue to donation checkout","membership"=>"Continue to membership checkout","volunteer"=>"Continue to volunteer signup",_=>"Continue to newsletter signup"}}<Icon name="external"/></a><p class="form-note">"Opens the selected service in a new tab. Opening it alone does not complete a payment or signup."</p><a class="text-link" href=url("/get-involved")>"Return to the work you can support"<Icon/></a></div>}.into_any()}else{view!{<form class="support-form" on:submit=move|ev|{ev.prevent_default();if busy.get_untracked()||key.get_untracked().is_empty(){return;}busy.set(true);error.set(String::new());let data=Submission{key:key.get_untracked(),kind:kind.get_value(),name:name.get_untracked(),email:email.get_untracked(),area:area.get_untracked(),amount:amount.get_untracked(),availability:availability.get_untracked(),message:message.get_untracked(),consent:consent.get_untracked(),website:website.get_untracked()};let nav=nav.clone();spawn_local(async move{match client::<Receipt>("POST","/api/support/requests",serde_json::to_value(data).unwrap()).await{Ok(_)=>{nav(&url(&format!("/support/confirmation/{}",key.get_untracked())),Default::default());},Err(e)=>error.set(e)}busy.set(false);});}>
            <span class="eyebrow">{label(&kind_value)}</span><h2>"Let’s start here."</h2><p class="support-form-intro">{if newsletter{"Leave your email and consent to register interest."}else{"A few details help the team understand how you would like to contribute."}}</p>
            {(!newsletter).then(||view!{<FormField id="support-name" label="Your name" value=name required=true max=160/>})}<FormField id="support-email" label="Email address" value=email input_type="email" required=true max=254/>
            {(!newsletter).then(||view!{<div class="support-field"><label for="support-area">"Area of interest"</label><select id="support-area" prop:value=move||area.get() on:change=move|e|area.set(event_target_value(&e))>{AREAS.iter().map(|(v,l)|view!{<option value=*v>{*l}</option>}).collect_view()}</select></div>})}
            {(kind_value=="giving").then(||view!{<FormField id="support-amount" label="Amount you have in mind (USD, optional)" value=amount input_type="number" max=7/><p class="form-note">"An indication of interest. No payment is collected on this form."</p>})}
            {(kind_value=="volunteer").then(||view!{<FormField id="support-availability" label="Location and availability (optional)" value=availability max=240/>})}
            {(!newsletter).then(||view!{<FormField id="support-message" label="Questions, skills, or ideas (optional)" value=message multiline=true/>})}
            <div class="support-honeypot" aria-hidden="true"><label for="support-website">"Leave this field empty"</label><input id="support-website" tabindex="-1" autocomplete="off" prop:value=move||website.get() on:input=move|e|website.set(event_target_value(&e))/></div>
            <label class="support-consent"><input type="checkbox" required prop:checked=move||consent.get() on:change=move|e|consent.set(event_target_checked(&e))/><span>{if newsletter{"I agree that the site team may store my email and contact me about future newsletter updates."}else{"I agree that the site team may store these details and contact me about this request."}}</span></label><p class="form-note">"This permission applies to this request. It does not add you to other mailing lists."</p>
            <p role="alert" class="support-error">{error}</p><Show when=move||key.get().is_empty()&&!error.get().is_empty()><button type="button" class="text-button" on:click=move|_|load()>"Reload the form"</button></Show><button type="submit" class="button button-green" disabled=move||busy.get()||key.get().is_empty()>{move||if busy.get(){"Saving your request…"}else{action(&kind.get_value())}}<Icon/></button><noscript><p>"Enable JavaScript to save a request, or use the Alliance’s official contact page."</p><a href="https://www.iditarod100.org/contact-us.html">"Contact information"</a></noscript>
        </form>}.into_any()}}
        </section>}
}

#[component]
pub fn Confirmation()->impl IntoView {
    let params=use_params_map();let refresh=RwSignal::new(0u64);let busy=RwSignal::new(false);let error=RwSignal::new(String::new());let confirm=RwSignal::new(false);
    let receipt=LocalResource::new(move||{let token=params.get().get("key").unwrap_or_default();let _=refresh.get();async move{client::<Receipt>("GET",&format!("/api/support/receipt/{token}"),Value::Null).await}});
    view!{<Title text="Your request | The Living Trail"/><Meta name="robots" content="noindex, nofollow"/><section class="container support-confirmation"><span class="eyebrow">"YOUR NEXT CHAPTER"</span><h1>"Your support request."</h1>{move||receipt.get().map(|result|match result{Ok(r)=>{let key=StoredValue::new(params.get_untracked().get("key").unwrap_or_default());view!{<div class="confirmation-record" role="status"><span class="confirmation-mark"><Icon name="check"/></span><h2>{if r.withdrawn{"Your request has been withdrawn."}else{match r.kind.as_str(){"giving"=>"Your giving enquiry is saved.","membership"=>"Your membership enquiry is saved.","volunteer"=>"Your volunteer offer is saved.",_=>"Your newsletter interest is saved."}}}</h2><p>{if r.withdrawn{"Your contact details have been removed from this request."}else{match r.kind.as_str(){"giving"=>"The site team can review your enquiry in Trail Studio. No payment has been taken.","membership"=>"The site team can review your enquiry. Membership has not yet been registered or renewed.","volunteer"=>"The site team can review your offer. A role or work date has not been assigned.",_=>"The site team can review your interest. You have not yet been subscribed to a mailing list."}}}</p><dl><div><dt>"Reference"</dt><dd>{r.reference}</dd></div><div><dt>"Request"</dt><dd>{label(&r.kind)}</dd></div><div><dt>"Interest"</dt><dd>{area_label(&r.area)}</dd></div></dl><p class="form-note">"Keep this private confirmation link. It lets you check or withdraw this request. No email receipt has been sent."</p></div>{(!r.withdrawn).then(||view!{<div class="withdraw-request"><Show when=move||confirm.get() fallback=move||view!{<button class="text-button" on:click=move|_|confirm.set(true)>"Withdraw this request"</button>}><p>"Withdraw this request and remove its contact details?"</p><div><button class="button button-green" disabled=busy on:click=move|_|{busy.set(true);let key=key.get_value();spawn_local(async move{match client::<Receipt>("POST",&format!("/api/support/withdraw/{key}"),json!({})).await{Ok(_)=>{confirm.set(false);refresh.update(|n|*n+=1);},Err(e)=>error.set(e)}busy.set(false);});}>"Yes, withdraw my request"</button><button class="text-button" on:click=move|_|confirm.set(false)>"Keep my request"</button></div></Show></div>})}}.into_any()},Err(_)=>view!{<div class="confirmation-record"><h2>"We couldn’t open this confirmation."</h2><p>"Check the complete link or try again. A request removed by the site team is no longer available here."</p><button class="button button-green" on:click=move|_|refresh.update(|n|*n+=1)>"Try again"</button></div>}.into_any()})}<Show when=move||receipt.get().is_none()><p role="status">"Opening your saved request…"</p></Show><p class="support-error" role="alert">{error}</p><div class="confirmation-next"><a class="button button-green" href=url("/get-involved#work-supported")>"Explore the work you can support"<Icon/></a><a class="text-link" href=url("/stories")>"Read a trail story"<Icon/></a></div></section>}
}

#[component]
pub fn Privacy()->impl IntoView {
    view!{<Title text="Your support request & privacy | The Living Trail"/><section class="container page-intro"><span class="eyebrow">"YOUR DETAILS, WITH CARE"</span><h1>"A clear understanding."</h1><p class="intro-copy">"What happens when you make a support request on this website."</p></section><section class="container prose support-privacy"><h2>"Who receives the request"</h2><p>"This website is being prepared for the Iditarod Historic Trail Alliance. Requests are saved for its website project team in the private Trail Studio inbox. Saving a request does not send it to the Alliance or an outside service."</p><h2>"What we keep"</h2><p>"We store the details you enter, your chosen area of interest, the date and your permission to be contacted. Newsletter interest uses only your email and permission. Please leave out payment details, identity documents, medical information, and other sensitive information."</p><h2>"How it is used"</h2><p>"Editors and administrators can review and follow up on requests. Administrators can export them for an approved follow-up process. A giving enquiry is not a payment, a membership enquiry is not membership, and newsletter interest is not a mailing-list subscription."</p><h2>"Your choice"</h2><p>"Use your private confirmation link to withdraw a request. Withdrawal removes the contact details and message from the active request; a reference and withdrawal record remain. Staff can delete a request entirely. Keep the link private because anyone with it can withdraw that request."</p><h2>"Retention and backups"</h2><p>"Requests remain in the private inbox until withdrawn or deleted by an administrator. Operational database backups are retained for up to 14 daily copies, so an earlier copy may remain until those backups expire. Previously exported copies must be handled by the team that received them."</p><h2>"External services"</h2><p>"When an approved checkout or signup service is linked, its privacy terms and confirmation process apply. This website does not receive card details or verify completion from a visit to that link."</p><a class="text-link" href=url("/get-involved")>"Return to ways to help"<Icon/></a></section>}
}
